commands:
git fetch origin "+refs/heads/main:refs/remotes/origin/main" || { echo "FETCH_FAILED" >&2; exit 1; }
BRANCH=$(.prflow/vendor/prflow/scripts/branch-for-issue.py 1834 --title-file .prflow/tmp/devflow-issue-1834-title.txt) || { echo "BRANCH_GEN_FAILED" >&2; exit 1; }
echo "BRANCH=$BRANCH"
[ -n "$BRANCH" ] || { echo "EMPTY_BRANCH" >&2; exit 1; }
git checkout -b "$BRANCH" "origin/main"
